package com.ecommerce.seller.security;
import java.io.IOException; import java.util.List;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.*; import jakarta.servlet.http.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final RestClient auth; private final String key;
 public JwtAuthenticationFilter(JwtService jwt,@Value("${services.auth.url:http://localhost:8081}") String url,@Value("${internal.service.key}") String key){this.jwt=jwt;auth=RestClient.builder().baseUrl(url).build();this.key=key;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader(HttpHeaders.AUTHORIZATION);if(h!=null&&h.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){String t=h.substring(7);if(jwt.isTokenValid(t)){Long id=jwt.extractUserId(t);State s=id==null?null:state(id);if(s!=null&&s.active()&&jwt.extractRole(t).equals(s.role())&&jwt.extractTokenVersion(t).equals(s.tokenVersion()))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AuthenticatedUser(id,jwt.extractEmail(t)),null,List.of(new SimpleGrantedAuthority("ROLE_"+s.role()))));}}chain.doFilter(req,res);}
 private State state(Long id){try{return auth.get().uri("/internal/auth/token-state/{id}",id).header("X-Internal-Service-Key",key).retrieve().body(State.class);}catch(Exception e){return null;}} private record State(Long userId,String role,boolean active,Long tokenVersion){}
}
